51	public class ArchivedTimelineV1 extends BaseTimelineV1 implements HoodieArchivedTimeline, HoodieInstantReader {
52	  private static final String HOODIE_COMMIT_ARCHIVE_LOG_FILE_PREFIX = "commits";
53	  private static final String ACTION_TYPE_KEY = "actionType";
54	  private static final String ACTION_STATE = "actionState";
55	  private static final String STATE_TRANSITION_TIME = "stateTransitionTime";
56	  private HoodieTableMetaClient metaClient;
57	  private final Map<String, byte[]> readCommits = new HashMap<>();
58	  private final ArchivedTimelineLoader timelineLoader = new ArchivedTimelineLoaderV1();
59	
60	  private static final Logger LOG = LoggerFactory.getLogger(org.apache.hudi.common.table.timeline.HoodieArchivedTimeline.class);
61	
62	  /**
63	   * Loads all the archived instants.
64	   * Note that there is no lazy loading, so this may not work if the archived timeline range is really long.
65	   * TBD: Should we enforce maximum time range?
66	   */
67	  public ArchivedTimelineV1(HoodieTableMetaClient metaClient) {
68	    this.metaClient = metaClient;
69	    setInstants(this.loadInstants(false));
70	    // multiple casts will make this lambda serializable -
71	    // http://docs.oracle.com/javase/specs/jls/se8/html/jls-15.html#jls-15.16
72	  }
73	
74	  /**
75	   * Loads completed instants from startTs(inclusive).
76	   * Note that there is no lazy loading, so this may not work if really early startTs is specified.
77	   */
78	  public ArchivedTimelineV1(HoodieTableMetaClient metaClient, String startTs) {
79	    this.metaClient = metaClient;
80	    setInstants(loadInstants(new StartTsFilter(startTs), true,
81	        record -> HoodieInstant.State.COMPLETED.toString().equals(record.get(ACTION_STATE).toString())));
82	    // multiple casts will make this lambda serializable -
83	    // http://docs.oracle.com/javase/specs/jls/se8/html/jls-15.html#jls-15.16
84	  }
