177	  private List<HoodieInstant> loadInstants(HoodieArchivedTimeline.TimeRangeFilter filter, boolean loadInstantDetails, Function<GenericRecord, Boolean> commitsFilter) {
178	    InstantsLoader loader = new InstantsLoader(loadInstantDetails);
179	    timelineLoader.loadInstants(metaClient, filter, LoadMode.PLAN, commitsFilter, loader);
180	    List<HoodieInstant> result = new ArrayList<>(loader.getInstantsInRangeCollected().values());
181	    Collections.sort(result);
182	    return result;
183	  }
