24	public interface HoodieArchivedTimeline extends HoodieTimeline {
25	
26	  String COMPLETION_TIME_ARCHIVED_META_FIELD = "completionTime";
27	
28	  void loadInstantDetailsInMemory(String startTs, String endTs);
29	
30	  void loadCompletedInstantDetailsInMemory();
31	
32	  void loadCompactionDetailsInMemory(String compactionInstantTime);
33	
34	  void loadCompactionDetailsInMemory(String startTs, String endTs);
35	
36	  void clearInstantDetailsFromMemory(String instantTime);
37	
38	  void clearInstantDetailsFromMemory(String startTs, String endTs);
39	
40	  HoodieArchivedTimeline reload();
41	
42	  HoodieArchivedTimeline reload(String startTs);
43	
44	  /**
45	   * Different mode for loading the archived instant metadata.
46	   */
47	  enum LoadMode {
48	    /**
49	     * Loads the instantTime, completionTime.
50	     */
51	    TIME,
52	    /**
53	     * Loads the instantTime, completionTime, action.
54	     */
55	    ACTION,
56	    /**
57	     * Loads the instantTime, completionTime, action, metadata.
58	     */
59	    METADATA,
60	    /**
61	     * Loads the instantTime, completionTime, action, plan.
62	     */
63	    PLAN,
64	    /**
65	     * Loads the instantTime, completionTime, action, plan, metadata.
66	     */
67	    FULL
68	  }
69	
70	  /**
71	   * A time based filter with range (startTs, endTs].
72	   */
73	  class TimeRangeFilter {
74	    protected final String startTs;
75	    protected final String endTs;
76	
77	    public TimeRangeFilter(String startTs, String endTs) {
78	      this.startTs = startTs;
79	      this.endTs = endTs;
80	    }
81	
82	    public boolean isInRange(String instantTime) {
83	      return InstantComparison.isInRange(instantTime, this.startTs, this.endTs);
84	    }
85	  }
86	
87	  /**
88	   * A time based filter with range [startTs, endTs).
89	   */
90	  class ClosedOpenTimeRangeFilter extends TimeRangeFilter {
91	
92	    public ClosedOpenTimeRangeFilter(String startTs, String endTs) {
93	      super(startTs, endTs);
94	    }
95	
96	    public boolean isInRange(String instantTime) {
97	      return InstantComparison.isInClosedOpenRange(instantTime, this.startTs, this.endTs);
98	    }
99	  }
100	
101	  /**
102	   * A time based filter with range [startTs, +&#8734).
103	   */
104	  class StartTsFilter extends TimeRangeFilter {
105	
106	    public StartTsFilter(String startTs) {
107	      super(startTs, null); // endTs is never used
108	    }
109	
110	    public boolean isInRange(String instantTime) {
111	      return compareTimestamps(instantTime, GREATER_THAN_OR_EQUALS, startTs);
112	    }
113	  }
114	
115	}
