68	    archivedMetaWrapper.setActionState(hoodieInstant.getState().name());
69	    archivedMetaWrapper.setStateTransitionTime(hoodieInstant.getCompletionTime());
70	    switch (hoodieInstant.getAction()) {
71	      case HoodieTimeline.CLEAN_ACTION: {
72	        if (hoodieInstant.isCompleted()) {
73	          archivedMetaWrapper.setHoodieCleanMetadata(CleanerUtils.getCleanerMetadata(metaClient, instantDetails.get()));
74	        } else {
75	          archivedMetaWrapper.setHoodieCleanerPlan(CleanerUtils.getCleanerPlan(metaClient, instantDetails.get()));
76	        }
77	        archivedMetaWrapper.setActionType(ActionType.clean.name());
78	        break;
79	      }
80	      case HoodieTimeline.COMMIT_ACTION: {
81	        HoodieCommitMetadata commitMetadata = metaClient.getCommitMetadataSerDe().deserialize(hoodieInstant, instantDetails.get(), HoodieCommitMetadata.class);
82	        archivedMetaWrapper.setHoodieCommitMetadata(convertCommitMetadata(commitMetadata));
83	        archivedMetaWrapper.setActionType(ActionType.commit.name());
84	        break;
85	      }
86	      case HoodieTimeline.DELTA_COMMIT_ACTION: {
87	        HoodieCommitMetadata deltaCommitMetadata = metaClient.getCommitMetadataSerDe().deserialize(hoodieInstant, instantDetails.get(), HoodieCommitMetadata.class);
88	        archivedMetaWrapper.setHoodieCommitMetadata(convertCommitMetadata(deltaCommitMetadata));
89	        archivedMetaWrapper.setActionType(ActionType.deltacommit.name());
90	        break;
91	      }
92	      case HoodieTimeline.REPLACE_COMMIT_ACTION:
93	      case HoodieTimeline.CLUSTERING_ACTION: {
94	        if (hoodieInstant.isCompleted()) {
95	          HoodieReplaceCommitMetadata replaceCommitMetadata = HoodieReplaceCommitMetadata.fromBytes(instantDetails.get(), HoodieReplaceCommitMetadata.class);
96	          archivedMetaWrapper.setHoodieReplaceCommitMetadata(convertReplaceCommitMetadataToAvro(replaceCommitMetadata));
97	        } else if (hoodieInstant.isInflight()) {
98	          // inflight replacecommit files have the same metadata body as HoodieCommitMetadata
99	          // so we could re-use it without further creating an inflight extension.
100	          // Or inflight replacecommit files are empty under clustering circumstance
101	          Option<HoodieCommitMetadata> inflightCommitMetadata = getInflightCommitMetadata(metaClient, hoodieInstant, instantDetails);
102	          if (inflightCommitMetadata.isPresent()) {
103	            archivedMetaWrapper.setHoodieInflightReplaceMetadata(convertCommitMetadata(inflightCommitMetadata.get()));
104	          }
105	        } else {
106	          // we may have cases with empty HoodieRequestedReplaceMetadata e.g. insert_overwrite_table or insert_overwrite
107	          // without clustering. However, we should revisit the requested commit file standardization
108	          Option<HoodieRequestedReplaceMetadata> requestedReplaceMetadata = getRequestedReplaceMetadata(instantDetails);
109	          if (requestedReplaceMetadata.isPresent()) {
110	            archivedMetaWrapper.setHoodieRequestedReplaceMetadata(requestedReplaceMetadata.get());
111	          }
112	        }
113	        archivedMetaWrapper.setActionType(
114	            hoodieInstant.getAction().equals(HoodieTimeline.REPLACE_COMMIT_ACTION) ? ActionType.replacecommit.name() : ActionType.clustering.name());
115	        break;
116	      }
117	      case HoodieTimeline.ROLLBACK_ACTION: {
118	        if (hoodieInstant.isCompleted()) {
119	          archivedMetaWrapper.setHoodieRollbackMetadata(TimelineMetadataUtils.deserializeAvroMetadata(instantDetails.get(), HoodieRollbackMetadata.class));
120	        }
121	        archivedMetaWrapper.setActionType(ActionType.rollback.name());
122	        break;
123	      }
124	      case HoodieTimeline.SAVEPOINT_ACTION: {
125	        archivedMetaWrapper.setHoodieSavePointMetadata(TimelineMetadataUtils.deserializeAvroMetadata(instantDetails.get(), HoodieSavepointMetadata.class));
126	        archivedMetaWrapper.setActionType(ActionType.savepoint.name());
127	        break;
128	      }
129	      case HoodieTimeline.COMPACTION_ACTION: {
130	        if (hoodieInstant.isRequested()) {
131	          HoodieCompactionPlan plan = CompactionUtils.getCompactionPlan(metaClient, instantDetails);
132	          archivedMetaWrapper.setHoodieCompactionPlan(plan);
133	        }
134	        archivedMetaWrapper.setActionType(ActionType.compaction.name());
135	        break;
136	      }
137	      case HoodieTimeline.LOG_COMPACTION_ACTION: {
138	        if (hoodieInstant.isRequested()) {
139	          HoodieCompactionPlan plan = CompactionUtils.getCompactionPlan(metaClient, instantDetails);
140	          archivedMetaWrapper.setHoodieCompactionPlan(plan);
141	        }
142	        archivedMetaWrapper.setActionType(ActionType.logcompaction.name());
143	        break;
144	      }
145	      default: {
146	        throw new UnsupportedOperationException("Action not fully supported yet");
147	      }
148	    }
149	    return archivedMetaWrapper;
